typedef unsigned int u_int;
typedef unsigned long long big_int;

class stringx;

class string_buf
{
  friend class stringx;
  friend inline bool operator==(const stringx &, const stringx &);

  big_int *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;

public:
  inline bool is_equal(const string_buf &buf) const
  {
    if (buf.block_length != block_length)
      return false;
    for (int i = 0; i < block_length; i++)
      if (!(buf.data[i] == data[i]))
        return false;
    return true;
  }
};

class stringx
{
  friend inline bool operator==(const stringx &, const stringx &);

  char *chars;
  string_buf *my_buf;

public:
  stringx();
  stringx(const stringx &);
  ~stringx();
  stringx &operator=(const char *);
  void to_upper();
};

inline bool operator==(const stringx &lhs, const stringx &rhs)
{
  return lhs.my_buf->is_equal(*rhs.my_buf);
}

enum { WAVE_LAST = 31 };

struct WaveData
{
  char name[32];
  char rest[584 - 32];
};

struct BeachData
{
  char name[32];
  char rest[532 - 32];
};

class game
{
  char pad[552];

public:
  int beach_id;
};

extern WaveData WaveDataArray[];
extern BeachData BeachDataArray[];
extern game *g_game_ptr;

static u_int WAVE_CheckWaveDataType(const stringx &wdstr)
{
  u_int wd_type = WAVE_LAST;

  stringx wd = wdstr;
  stringx cwd;
  bool retried = false;
retry:
  wd.to_upper();
  for (u_int i = 0; i < WAVE_LAST; ++i)
  {
    cwd = WaveDataArray[i].name;
    cwd.to_upper();
    if (wd == cwd)
    {
      wd_type = i;
      break;
    }
  }
  if (wd_type == WAVE_LAST)
  {
    if (retried)
    {
      wd_type = 0;
    }
    else
    {
      int curbeach = g_game_ptr->beach_id;
      wd = BeachDataArray[curbeach].name;
      retried = true;
      goto retry;
    }
  }

  return wd_type;
}
